import {
  configFilePath,
  readFullConfig,
  writeFullConfig,
  resolveEffectiveProfileName,
  ConfigError,
  validateTimeoutMs,
  validateProfileName,
} from "@bithumb-official/bithumb-core";
import type { BithumbTomlConfig, BithumbProfile } from "@bithumb-official/bithumb-core";
import type { CliValues } from "../parser.js";
import { outputLine, errorLine, printJson, printKv, printTable } from "../formatter.js";
import { existsSync } from "node:fs";
import { createInterface } from "node:readline";

export type Prompter = (question: string) => Promise<string>;

export interface ConfigDeps {
  prompt?: Prompter;
}

// Resolve the prompter to use. When the caller injects one (tests), there is
// nothing to close. Otherwise build a readline-backed prompter and return its
// close handle so the command can release stdin when the wizard finishes.
// Uses the line async-iterator rather than sequential rl.question: the latter
// hangs after the first prompt when stdin is a pipe rather than a TTY.
// The prompter returns the raw line; trimming is the caller's job so the DI and
// readline paths behave identically (an injected prompter does not trim).
function resolvePrompter(deps?: ConfigDeps): { prompt: Prompter; close: () => void } {
  if (deps?.prompt) return { prompt: deps.prompt, close: () => {} };
  const rl = createInterface({ input: process.stdin, output: process.stdout, terminal: false });
  const lines = rl[Symbol.asyncIterator]();
  const prompt: Prompter = async (question) => {
    process.stdout.write(question);
    const { value, done } = await lines.next();
    // EOF (closed stdin / too few piped lines) is not an empty Enter — abort so
    // the wizard never writes a profile with missing credentials.
    if (done) {
      throw new ConfigError(
        "Unexpected end of input while prompting.",
        "Provide a value for every prompt, or run the command interactively.",
      );
    }
    return value;
  };
  return { prompt, close: () => rl.close() };
}

export function handleConfigCommand(
  action: string,
  rest: string[],
  v: CliValues,
  deps?: ConfigDeps,
): void | Promise<void> {
  const json = v.json ?? false;
  switch (action) {
    case "show":
      return cmdConfigShow(json, v.profile);
    case "init":
      return cmdConfigInit(deps);
    case "set":
      if (rest[0] === undefined) {
        return cmdConfigSetWizard(v.profile, deps);
      }
      return cmdConfigSet(rest[0], rest[1], v.profile);
    case "add-profile":
      return cmdConfigAddProfile(rest, deps);
    case "list-profiles":
      return cmdConfigListProfiles(json);
    case "use":
      return cmdConfigUse(rest[0]);
    case "path":
      outputLine(configFilePath());
      return;
    default:
      if (!action) {
        return cmdConfigShow(json, v.profile);
      }
      errorLine(`Unknown config command: ${action}. Available: show, init, set, add-profile, list-profiles, use, path`);
      process.exitCode = 1;
  }
}

// Validate a profile name at the single CLI write point (ADR 0013), reporting a
// friendly error and setting exitCode instead of throwing. Returns false when
// invalid so the caller can bail. Shared by add-profile and init so the
// positional and prompt paths cannot diverge.
// A wizard step can fail validation (timeout_ms) or hit EOF (resolvePrompter).
// Both surface as ConfigError: report it and set exitCode, leaving the config
// unwritten. Returns true when handled; non-ConfigError is rethrown by callers.
function reportWizardError(err: unknown): boolean {
  if (err instanceof ConfigError) {
    errorLine(err.message);
    process.exitCode = 1;
    return true;
  }
  return false;
}

function validateProfileNameOrReport(name: string): boolean {
  try {
    validateProfileName(name);
    return true;
  } catch (err) {
    errorLine(err instanceof ConfigError ? err.message : String(err));
    process.exitCode = 1;
    return false;
  }
}

function readOnlyDisplay(p: BithumbProfile): string {
  // CONTEXT.md "Read-only": an unset read_only means writes are allowed.
  if (p.read_only === undefined) return "(not set → writes allowed)";
  return p.read_only ? "true (read-only — writes blocked)" : "false (writes allowed)";
}

// JSON-safe masking: hide credentials but keep every other field — crucially
// read_only stays a raw boolean/undefined so the read-only gate can parse it
// (ADR 0010). The human-readable profileKv() is text-only and would break that.
function maskedProfile(p: BithumbProfile): BithumbProfile {
  const masked = { ...p };
  if (masked.access_key) masked.access_key = `${masked.access_key.slice(0, 8)}...`;
  if (masked.secret_key) masked.secret_key = "***";
  return masked;
}

function maskedProfiles(profiles: Record<string, BithumbProfile>): Record<string, BithumbProfile> {
  return Object.fromEntries(Object.entries(profiles).map(([name, p]) => [name, maskedProfile(p)]));
}

function profileKv(p: BithumbProfile): Record<string, unknown> {
  return {
    access_key: p.access_key ? `${p.access_key.slice(0, 8)}...` : "(not set)",
    secret_key: p.secret_key ? "***" : "(not set)",
    ...(p.base_url ? { base_url: p.base_url } : {}),
    ...(p.timeout_ms ? { timeout_ms: p.timeout_ms } : {}),
    read_only: readOnlyDisplay(p),
  };
}

// ADR 0014 (supersedes 0010's hard code gate): when the effective profile is
// read-only, attach a structured notice to `config show --json` so the agent
// learns up front that writes are blocked and which profiles can write — and
// can skip wasted write-preflight lookups *by its own judgement*, with no code
// gate intercepting the reads. Returns undefined for write-capable profiles so
// the key is simply absent (no notice noise on the common path).
function readOnlyNotice(
  config: BithumbTomlConfig,
  profile: BithumbProfile | undefined,
): { blocked_for_writes: true; write_capable_profiles: string[]; guidance: string } | undefined {
  if (profile?.read_only !== true) return undefined;
  const writeCapable = Object.entries(config.profiles)
    .filter(([, p]) => p.read_only !== true)
    .map(([name]) => name);
  return {
    blocked_for_writes: true,
    write_capable_profiles: writeCapable,
    guidance:
      "Effective profile is read-only — real orders, withdrawals, and deposits are blocked. " +
      "Skip write-preflight lookups (order-chance, withdraw chance, wallet-status, withdraw addresses, fee-inout); " +
      "they prepare a write that cannot run. List the write-capable profiles to the user and let them pick one " +
      "with --profile <name>. Do not auto-select a profile or disable read-only on the user's behalf.",
  };
}

function cmdConfigShow(json: boolean, profileName?: string): void {
  const config = readFullConfig();
  const effective = resolveEffectiveProfileName(config, profileName);

  // --profile X (explicit): show only that profile so the agent reads one value
  // without re-deriving which profile applies (ADR 0010).
  if (profileName !== undefined) {
    const p = config.profiles[profileName];
    if (json) {
      if (!p) {
        // Match the text path's exitCode=1 so the gate never reads a missing
        // profile as a silent success.
        process.exitCode = 1;
        return printJson({ profile: profileName, settings: null, error: "profile_not_found" });
      }
      const notice = readOnlyNotice(config, p);
      return printJson({
        profile: profileName,
        settings: maskedProfile(p),
        ...(notice ? { read_only_notice: notice } : {}),
      });
    }
    outputLine(`Config file: ${configFilePath()}`);
    if (!p) {
      errorLine(`Profile '${profileName}' not found. Run 'bithumb config list-profiles' to see available profiles.`);
      process.exitCode = 1;
      return;
    }
    outputLine(`Profile: ${profileName} (effective)`);
    outputLine("");
    outputLine(`[${profileName}]`);
    printKv(profileKv(p));
    return;
  }

  if (json) {
    const notice = readOnlyNotice(config, config.profiles[effective]);
    return printJson({
      ...config,
      profiles: maskedProfiles(config.profiles),
      effective_profile: effective,
      ...(notice ? { read_only_notice: notice } : {}),
    });
  }
  outputLine(`Config file: ${configFilePath()}`);
  if (config.default_profile) {
    outputLine(`Default profile: ${config.default_profile}`);
  }
  outputLine(`Effective profile: ${effective}`);
  outputLine("");
  const profileNames = Object.keys(config.profiles);
  if (profileNames.length === 0) {
    outputLine("No profiles configured. Run 'bithumb config init' to create one.");
    return;
  }
  for (const name of profileNames) {
    const p = config.profiles[name];
    outputLine(`[${name}]${name === effective ? " ← effective" : ""}`);
    printKv(profileKv(p));
    outputLine("");
  }
}

async function cmdConfigInit(deps?: ConfigDeps): Promise<void> {
  const path = configFilePath();
  if (existsSync(path)) {
    outputLine(`Config file already exists: ${path}`);
    outputLine("Use 'bithumb config add-profile <name>' to add a new profile, or");
    outputLine("'bithumb config set' to update the current profile.");
    return;
  }

  const { prompt, close } = resolvePrompter(deps);
  try {
    const profileInput = await prompt("Profile name (default): ");
    const profileName = profileInput.trim() || "default";
    if (!validateProfileNameOrReport(profileName)) return;
    const profile = await runProfileWizard(prompt, {});

    const config: BithumbTomlConfig = {
      default_profile: profileName,
      profiles: { [profileName]: profile },
    };
    writeFullConfig(config);
    outputLine(`\n✓ Config file created: ${path}`);
  } catch (err) {
    if (!reportWizardError(err)) throw err;
  } finally {
    close();
  }
}

function maskHint(value: string | undefined, reveal = false): string {
  if (!value) return "";
  return reveal ? `${value.slice(0, 8)}...` : "***";
}

async function runProfileWizard(
  prompt: Prompter,
  existing: BithumbProfile,
): Promise<BithumbProfile> {
  const accessHint = maskHint(existing.access_key, true);
  const access = (await prompt(`Access key${accessHint ? ` [${accessHint}]` : ""}: `)).trim();
  const secretHint = maskHint(existing.secret_key);
  const secret = (await prompt(`Secret key${secretHint ? ` [${secretHint}]` : ""}: `)).trim();
  const roHint = existing.read_only === undefined ? "" : ` [${existing.read_only ? "y" : "N"}]`;
  const ro = (await prompt(`Read-only? (y/N)${roHint}: `)).trim();
  // Advanced infrastructure field comes last so the common credential path is
  // unchanged in feel (ADR 0008 amendment). Empty input keeps the existing value.
  const timeoutHint = existing.timeout_ms === undefined ? "" : ` [${existing.timeout_ms}]`;
  const timeout = (await prompt(`Timeout (ms)${timeoutHint}: `)).trim();

  const next = { ...existing };
  if (access !== "") next.access_key = access;
  if (secret !== "") next.secret_key = secret;
  if (ro !== "") next.read_only = /^y(es)?$/i.test(ro);
  if (timeout !== "") next.timeout_ms = validateTimeoutMs(Number(timeout));
  return next;
}

async function cmdConfigSetWizard(profileName?: string, deps?: ConfigDeps): Promise<void> {
  const config = readFullConfig();
  const name = profileName ?? config.default_profile ?? "default";
  // ADR 0008: `set` (no args) edits an *existing* target profile; creating new
  // profiles is add-profile's job. Reject a missing target rather than silently
  // creating it, and route the user to the right command.
  if (!config.profiles[name]) {
    if (Object.keys(config.profiles).length === 0) {
      errorLine("No profiles configured. Run 'bithumb config init' to create your first profile.");
    } else {
      errorLine(`Profile '${name}' does not exist. Run 'bithumb config add-profile ${name}' to create it.`);
    }
    process.exitCode = 1;
    return;
  }
  const { prompt, close } = resolvePrompter(deps);
  try {
    config.profiles[name] = await runProfileWizard(prompt, config.profiles[name]);
    writeFullConfig(config);
    outputLine(`Updated profile '${name}'`);
  } catch (err) {
    if (!reportWizardError(err)) throw err;
  } finally {
    close();
  }
}

function cmdConfigSet(key: string | undefined, value: string | undefined, profileName?: string): void {
  if (!key || value === undefined) {
    errorLine("Usage: bithumb config set <key> <value> [--profile <name>]");
    errorLine("Keys: access_key, secret_key, timeout_ms, read_only");
    process.exitCode = 1;
    return;
  }
  const validKeys = new Set(["access_key", "secret_key", "timeout_ms", "read_only"]);
  if (!validKeys.has(key)) {
    errorLine(`Invalid key: ${key}. Valid keys: ${[...validKeys].join(", ")}`);
    process.exitCode = 1;
    return;
  }
  // Validate before reading/writing the config so a bad value never reaches the
  // file (ADR 0013): the `Set ...` success line must not lie.
  let parsed: string | number | boolean = value;
  if (key === "timeout_ms") {
    try {
      parsed = validateTimeoutMs(Number(value));
    } catch (err) {
      errorLine(err instanceof ConfigError ? err.message : String(err));
      process.exitCode = 1;
      return;
    }
  } else if (key === "read_only") {
    if (value !== "true" && value !== "false") {
      errorLine(`Invalid read_only: ${value}. Use 'true' or 'false'.`);
      process.exitCode = 1;
      return;
    }
    parsed = value === "true";
  }
  const config = readFullConfig();
  const name = profileName ?? config.default_profile ?? "default";
  if (!config.profiles[name]) {
    config.profiles[name] = {};
  }
  (config.profiles[name] as Record<string, unknown>)[key] = parsed;
  writeFullConfig(config);
  outputLine(`Set ${name}.${key}`);
}

async function cmdConfigAddProfile(rest: string[], deps?: ConfigDeps): Promise<void> {
  const { prompt, close } = resolvePrompter(deps);
  try {
    // ADR 0008: add-profile is dual-mode like `set`. With a positional name it
    // is scriptable; without one it prompts. Either way the name is trimmed and
    // an empty name is rejected at this single point, so both paths agree.
    const name = (rest[0] ?? (await prompt("Profile name: "))).trim();
    if (!validateProfileNameOrReport(name)) return;
    const config = readFullConfig();
    // Reject a duplicate before asking for credentials, so the user is not made
    // to type a key and secret only to be turned away.
    if (config.profiles[name]) {
      errorLine(`Profile '${name}' already exists.`);
      process.exitCode = 1;
      return;
    }
    const isFirstProfile = Object.keys(config.profiles).length === 0;
    config.profiles[name] = await runProfileWizard(prompt, {});
    // A profile is unusable until something selects it: an empty default_profile
    // falls back to "default", which won't match the name just added. Promote the
    // first profile so the user isn't left pointing at a nonexistent default.
    if (isFirstProfile && !config.default_profile) {
      config.default_profile = name;
    }
    writeFullConfig(config);
    outputLine(`Profile '${name}' added.`);
  } catch (err) {
    if (!reportWizardError(err)) throw err;
  } finally {
    close();
  }
}

function cmdConfigListProfiles(json: boolean): void {
  const config = readFullConfig();
  const profiles = Object.entries(config.profiles).map(([name, p]) => ({
    name,
    default: name === (config.default_profile ?? "default") ? "*" : "",
    has_credentials: p.access_key && p.secret_key ? "yes" : "no",
  }));
  if (json) return printJson(profiles);
  if (profiles.length === 0) {
    outputLine("No profiles configured.");
    return;
  }
  printTable(profiles);
}

function cmdConfigUse(profileName: string | undefined): void {
  if (!profileName) {
    errorLine("Usage: bithumb config use <profile-name>");
    process.exitCode = 1;
    return;
  }
  const config = readFullConfig();
  if (!config.profiles[profileName]) {
    errorLine(`Profile '${profileName}' not found. Run 'bithumb config list-profiles' to see available profiles.`);
    process.exitCode = 1;
    return;
  }
  config.default_profile = profileName;
  writeFullConfig(config);
  outputLine(`Default profile set to '${profileName}'`);
}
